if (__gptFunctionCallHistory && __gptFunctionCallHistory.length > 0) { 

    var __lastHistoryIndex = __gptFunctionCallHistory.length - 1;

    __gptFunctionCallHistory[__lastHistoryIndex].result = __gptActionResult;
    __gptFunctionCallHistory[__lastHistoryIndex].speakFlowIndexResultSet = context.speakFlow.size - 1; // this will update the order of the result (needed for proper Dialog Node OnEntry handling)

    if (__logPrompt) log_debug('Action result (' + __gptFunctionCallHistory[__lastHistoryIndex].name + '): ' + __gptActionResult + ', functionCallIndex: ' + __gptFunctionCallHistory[__lastHistoryIndex].speakFlowIndexResultSet + ', resultIndex: ' + __gptFunctionCallHistory[__lastHistoryIndex].speakFlowIndexResultSet); 
} else { 
    if (__logPrompt) log_debug('Cant set action result!'); 
}
